Object.assign(SNIP,{"l26param": "void tang(int& v) { v++; }                  // sửa được biến của nơi gọi\nint dem(const string& s, char c) {           // const&: không chép chuỗi, chỉ đọc\n    int d = 0;\n    for (char x : s) if (x == c) d++;\n    return d;\n}\nvector<int> v = {1, 2, 3};\nfor (int& e : v) e *= 10;                    // e gắn vào từng phần tử: sửa thẳng v\nfor (const int& e : v) cout << e << \" \";     // chỉ đọc, không chép", "l26ret": "int& lonNhat(int a[], int n) {     // trả về TÊN của ô lớn nhất, không phải bản sao\n    int k = 0;\n    for (int i = 1; i < n; i++) if (a[i] > a[k]) k = i;\n    return a[k];                   // a[k] thuộc mảng của nơi gọi: vẫn sống sau hàm\n}\n// gọi: lonNhat(a, 5) = 0;   (gán thẳng vào phần tử lớn nhất)", "l26decl": "int x = 5;\nint& r = x;       // r là tên thứ hai của x (phải gắn ngay khi khai báo)\nr = 9;            // x cũng thành 9: r và x là MỘT ô nhớ\ncout << &r;       // in đúng địa chỉ của x\nint y = 2;\nr = y;            // KHÔNG đổi chỗ gắn: chép giá trị 2 vào x"});PRESET_NOTES["l26"]={"Ví dụ: Tham chiếu là tên thứ hai": "r không có ô riêng: &r và &x là cùng một địa chỉ (in ra 1, tức true). r = y không làm r gắn sang y mà chép 2 vào x; sau đó đổi y thành 100 cũng không ảnh hưởng gì tới x.", "Ví dụ: Truyền giá trị và truyền tham chiếu": "tangGiaTri có ô v riêng (bản sao của a) nên a vẫn là 1. Trong tangThamChieu, v là mũi tên chỉ về b của main, nên b thành 2. dem nhận const string&: không chép chuỗi, và không thể lỡ tay sửa nó.", "Ví dụ: Sửa vector bằng for (int& e : v)": "Vòng đầu, e là bản sao: nhân 10 rồi bỏ đi, v[0] vẫn là 1. Vòng thứ hai, e gắn lần lượt vào từng phần tử nên v được nhân 10 thật. Vòng cuối chỉ đọc qua const int&.", "Ví dụ: Hàm trả về tham chiếu": "Lần gọi đầu trả về chính ô a[1] (giá trị 9) nên gán 0 vào đó. Lần thứ hai, lớn nhất là a[3] = 7, cộng thêm 100. Hàm trả về được tham chiếu vì a[k] thuộc mảng của main, vẫn sống sau khi hàm kết thúc.", "Ví dụ: Đổi con trỏ bên trong hàm (int*&)": "p trong chonLon là tham chiếu tới con trỏ p của main, nên gán p = &b đổi luôn con trỏ của main. Sau lời gọi, p của main trỏ vào y; *p = 0 làm y thành 0. Nếu tham số chỉ là int* p, hàm chỉ đổi bản sao và p của main vẫn là nullptr.", "Lỗi: tham chiếu thường gắn vào giá trị tạm": "x + 1 là một giá trị tạm, không có ô nhớ cố định nên tham chiếu thường không gắn vào được: g++ báo cannot bind non-const lvalue reference. Sửa: int y = x + 1; rồi gắn vào y, hoặc dùng const int& r = x + 1; nếu chỉ cần đọc.", "Lỗi: trả về tham chiếu tới biến cục bộ": "x là biến cục bộ của taoSo, bị hủy ngay khi hàm kết thúc; r gắn vào một ô đã chết (tham chiếu treo). g++ cảnh báo reference to local variable 'x' returned, và chương trình bị dừng. Sửa: cho hàm trả về int (giá trị), không phải int&."};EX_HINTS["l26"]=[["Ba lần so sánh là đủ: (a, b), rồi (b, c) để đưa số lớn nhất về c, rồi (a, b) lần nữa.", "Vì a, b, c là tham chiếu, swap(a, b) đổi chỗ thẳng hai biến x, y của main."], ["Hàm trả hai kết quả bằng cách ghi vào hai tham số tham chiếu dem và tong.", "Nhớ gán dem = 0, tong = 0 ở đầu hàm: biến của main chưa được khởi tạo. Tổng có thể vượt int nên tong là long long."], ["So sánh bằng > (không phải >=) để khi trùng thì giữ phần tử đứng trước.", "v là tham chiếu tới vector của main nên v[k] vẫn sống sau hàm: trả về tham chiếu tới nó là an toàn."]];
/* ===================== BÀI 26 · Tham chiếu ===================== */
/* Bài 26 · Tham chiếu
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const P26=[{label:"Ví dụ: Tham chiếu là tên thứ hai",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int x = 5;\n    int& r = x;\n    r = 9;\n    cout << \"x = \" << x << \"\\n\";\n    cout << (&r == &x) << \"\\n\";\n    int y = 2;\n    r = y;\n    y = 100;\n    cout << \"x = \" << x << \", y = \" << y << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Truyền giá trị và truyền tham chiếu",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nvoid tangGiaTri(int v) {\n    v++;\n}\n\nvoid tangThamChieu(int& v) {\n    v++;\n}\n\nint dem(const string& s, char c) {\n    int d = 0;\n    for (char x : s) {\n        if (x == c) d++;\n    }\n    return d;\n}\n\nint main() {\n    int a = 1, b = 1;\n    tangGiaTri(a);\n    tangThamChieu(b);\n    cout << \"a = \" << a << \", b = \" << b << \"\\n\";\n    cout << dem(\"banana\", 'a') << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Sửa vector bằng for (int& e : v)",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {1, 2, 3, 4};\n    for (int e : v) {\n        e *= 10;\n    }\n    cout << v[0] << \"\\n\";\n    for (int& e : v) {\n        e *= 10;\n    }\n    for (const int& e : v) {\n        cout << e << \" \";\n    }\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Hàm trả về tham chiếu",input:"",code:"#include <iostream>\nusing namespace std;\n\nint& lonNhat(int a[], int n) {\n    int k = 0;\n    for (int i = 1; i < n; i++) {\n        if (a[i] > a[k]) k = i;\n    }\n    return a[k];\n}\n\nint main() {\n    int a[5] = {4, 9, 2, 7, 5};\n    lonNhat(a, 5) = 0;\n    lonNhat(a, 5) += 100;\n    for (int i = 0; i < 5; i++) cout << a[i] << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Đổi con trỏ bên trong hàm (int*&)",input:"",code:"#include <iostream>\nusing namespace std;\n\nvoid chonLon(int*& p, int& a, int& b) {\n    if (a > b) p = &a;\n    else p = &b;\n}\n\nint main() {\n    int x = 3, y = 8;\n    int* p = nullptr;\n    chonLon(p, x, y);\n    *p = 0;\n    cout << \"x = \" << x << \", y = \" << y << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: tham chiếu thường gắn vào giá trị tạm",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int x = 4;\n    int& r = x + 1;\n    cout << r << \"\\n\";\n    return 0;\n}"},{label:"Lỗi: trả về tham chiếu tới biến cục bộ",input:"",code:"#include <iostream>\nusing namespace std;\n\nint& taoSo() {\n    int x = 42;\n    return x;\n}\n\nint main() {\n    int& r = taoSo();\n    cout << r << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]}];
const sim26=makeSim2(document.getElementById("sim-l26"),{id:"s26",presets:P26});
makeEx2(document.getElementById("ex-l26"),sim26,[{t:"Sắp xếp ba số bằng tham chiếu",d:"Nhập ba số nguyên. Viết hàm <code>void sapXep3(int&amp; a, int&amp; b, int&amp; c)<\/code> đổi chỗ để sau khi gọi a ≤ b ≤ c. Trong main gọi <code>sapXep3(x, y, z)<\/code> rồi in x y z.",tests:[{in:"3 1 2",out:"1 2 3"},{in:"5 5 1",out:"1 5 5"},{in:"-1 -2 -3",out:"-3 -2 -1"},{in:"7 8 9",out:"7 8 9"}],start:"#include <iostream>\nusing namespace std;\n\nvoid sapXep3(int& a, int& b, int& c) {\n    // so sánh từng cặp và đổi chỗ khi sai thứ tự (có thể dùng swap)\n}\n\nint main() {\n    int x, y, z;\n    cin >> x >> y >> z;\n    sapXep3(x, y, z);\n    cout << x << \" \" << y << \" \" << z << \"\\n\";\n    return 0;\n}",need:/void\s+sapXep3\s*\(\s*int\s*&\s*\w+\s*,\s*int\s*&\s*\w+\s*,\s*int\s*&\s*\w+\s*\)[\s\S]*sapXep3\s*\(\s*x\s*,\s*y\s*,\s*z\s*\)/,needMsg:"Hãy giữ hàm void sapXep3(int& a, int& b, int& c) và gọi sapXep3(x, y, z)."},{t:"Thống kê số dương",d:"Nhập n (1 ≤ n ≤ 10<sup>5<\/sup>) rồi n số nguyên (|x| ≤ 10<sup>9<\/sup>). Viết hàm <code>void thongKe(const vector&lt;int&gt;&amp; v, int&amp; dem, long long&amp; tong)<\/code> đếm số phần tử dương và tính tổng của chúng. In hai số đó cách nhau một dấu cách.",tests:[{in:"5\n3 -1 4 0 5",out:"3 12"},{in:"3\n-1 -2 -3",out:"0 0"},{in:"1\n1000000000",out:"1 1000000000"},{in:"4\n1000000000 1000000000 1000000000 -5",out:"3 3000000000"}],start:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nvoid thongKe(const vector<int>& v, int& dem, long long& tong) {\n    // gán dem, tong về 0 rồi duyệt v (đọc bằng const int&)\n}\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> v(n);\n    for (int& x : v) cin >> x;\n    int dem;\n    long long tong;\n    thongKe(v, dem, tong);\n    cout << dem << \" \" << tong << \"\\n\";\n    return 0;\n}",need:/void\s+thongKe\s*\(\s*const\s+vector\s*<\s*int\s*>\s*&\s*\w+\s*,\s*int\s*&\s*\w+\s*,\s*long\s+long\s*&\s*\w+\s*\)/,needMsg:"Hãy giữ đúng hàm void thongKe(const vector<int>& v, int& dem, long long& tong)."},{t:"Hạ phần tử lớn nhất",d:"Nhập n (1 ≤ n ≤ 1000), n số nguyên, rồi k (1 ≤ k ≤ 1000). Viết hàm <code>int&amp; lonNhat(vector&lt;int&gt;&amp; v)<\/code> trả về tham chiếu tới phần tử lớn nhất (nếu trùng, lấy phần tử đứng trước). Gọi <code>lonNhat(v) = 0;<\/code> đúng k lần rồi in vector.",tests:[{in:"5\n3 9 2 9 4\n2",out:"3 0 2 0 4"},{in:"3\n1 2 3\n1",out:"1 2 0"},{in:"4\n5 1 5 1\n3",out:"0 0 0 1"},{in:"1\n-7\n2",out:"0"}],start:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint& lonNhat(vector<int>& v) {\n    int k = 0;\n    // tìm chỉ số k của phần tử lớn nhất\n    return v[k];\n}\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> v(n);\n    for (int& x : v) cin >> x;\n    int k;\n    cin >> k;\n    for (int i = 0; i < k; i++) lonNhat(v) = 0;\n    for (int x : v) cout << x << \" \";\n    cout << \"\\n\";\n    return 0;\n}",need:/int\s*&\s*lonNhat\s*\(\s*vector\s*<\s*int\s*>\s*&\s*\w+\s*\)[\s\S]*lonNhat\s*\(\s*v\s*\)\s*=\s*0/,needMsg:"Hãy giữ hàm int& lonNhat(vector<int>& v) và dòng lonNhat(v) = 0; trong main."}]);

makeQuiz("quiz26","score26",[{"q": "<code>int x = 1; int&amp; r = x; int y = 5; r = y; y = 9;<\/code> Lúc này x bằng bao nhiêu?", "o": ["1", "5", "9", "Lỗi biên dịch"], "a": 1, "e": "r = y không gắn r sang y mà chép 5 vào x (r là x). Đổi y sau đó không ảnh hưởng tới x."}, {"q": "Dòng nào gây lỗi biên dịch?", "o": ["<code>int&amp; r;<\/code>", "<code>const int&amp; r = 5;<\/code>", "<code>int x = 2; int&amp; r = x;<\/code>", "<code>int* p = nullptr;<\/code>"], "a": 0, "e": "Tham chiếu phải được gắn vào một biến ngay khi khai báo. const int& gắn được vào giá trị tạm như 5."}, {"q": "Vì sao nên viết <code>int dem(const string&amp; s)<\/code> thay vì <code>int dem(string s)<\/code>?", "o": ["Để hàm sửa được chuỗi", "Để không phải chép chuỗi, và hàm không sửa được nó", "Vì string không truyền theo giá trị được", "Để chuỗi được tự động xóa sau khi gọi"], "a": 1, "e": "Truyền giá trị thì chép cả chuỗi mỗi lần gọi. const& dùng thẳng chuỗi gốc mà vẫn bảo đảm hàm chỉ đọc."}, {"q": "<code>vector&lt;int&gt; v = {1, 2}; for (int e : v) e = 0;<\/code> Sau vòng lặp v là gì?", "o": ["{0, 0}", "{1, 2}", "{0, 2}", "Lỗi biên dịch"], "a": 1, "e": "e là bản sao của từng phần tử, gán e = 0 không đổi v. Muốn sửa phải viết for (int& e : v)."}]);

